function pageForName(name) {
  const idx = parseInt((name.match(/^\d+/) || ['0'])[0], 10);
  if (idx >= 37 && idx <= 46) return '02 Modals & Sheets';
  if (idx >= 47 && idx <= 51) return '03 Responsive & Modes';
  if (idx >= 52) return '04 System & States';
  return '01 Full App Screens';
}
async function main() {
  figma.showUI('<p style="font-family:Inter, sans-serif; padding:16px">Creating Hermes Desktop design artboards…</p>', { width: 300, height: 80 });
  const pages = {};
  for (const p of ['01 Full App Screens','02 Modals & Sheets','03 Responsive & Modes','04 System & States']) {
    const page = figma.createPage();
    page.name = p;
    pages[p] = page;
  }
  const positions = {};
  for (const board of ARTBOARDS) {
    const pageName = pageForName(board.name);
    const page = pages[pageName];
    figma.currentPage = page;
    if (!positions[pageName]) positions[pageName] = {x: 0, y: 0, col: 0, row: 0};
    const pos = positions[pageName];
    const frame = figma.createFrame();
    frame.name = board.name;
    frame.resize(board.width, board.height);
    frame.x = 80 + pos.col * 1520;
    frame.y = 80 + pos.row * 1120;
    frame.fills = [];
    const imported = figma.createNodeFromSvg(board.svg);
    imported.name = board.name + ' · editable SVG layers';
    imported.x = 0;
    imported.y = 0;
    frame.appendChild(imported);
    page.appendChild(frame);
    pos.col += 1;
    if (pos.col >= 3) { pos.col = 0; pos.row += 1; }
  }
  figma.currentPage = pages['01 Full App Screens'];
  figma.viewport.scrollAndZoomIntoView(figma.currentPage.children);
  figma.closePlugin('Hermes Desktop design package imported. You can now export this Figma file as .fig from Figma.');
}
main();
